    T& operator[](unsigned int i);
    T& operator()(unsigned int i);
	Point3<T> operator += (const Point3<T>& otherPoint);
	Point3<T> operator -= (const Point3<T>& otherPoint);
	Point3<T> operator *= (const T& scalar);
	Point3<T> operator *= (const Point3<T>& otherPoint);
	Point3<T> operator /= (const T& scalar );
	Point3<T> operator /= (const Point3<T>& otherPoint);

protected:
